@@ -0,0 +1,25 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { memoryStore } from "../src/db/store.js";
+import { stockValue } from "../src/domain/reports.js";
+import { seed } from "./helpers.js";
+
+test("stock value total is the sum of its rounded lines", () => {
+  const data = seed();
+  data.items = [
+    { ...data.items[0], id: 1, priceCents: 1 },
+    { ...data.items[0], id: 2, sku: "X-2", priceCents: 1 },
+  ];
+  data.batches = [
+    { ...data.batches[0], id: 1, itemId: 1, qty: 0.5 },
+    { ...data.batches[0], id: 2, itemId: 2, qty: 0.5 },
+  ];
+  const report = stockValue(memoryStore(data));
+  assert.deepEqual(report.lines.map((l) => l.valueCents), [1, 1]);
+  assert.equal(report.totalCents, 2);
+});
+
+test("stock value total matches its lines for the seed data", () => {
+  const report = stockValue(memoryStore(seed()));
+  assert.equal(report.totalCents, report.lines.reduce((s, l) => s + l.valueCents, 0));
+});
